-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/silver/silver_patient_link.sql. Do not edit.
-- Silver patient link: one row per Patient.link, the records the EMPI (empi/match.py) found to be the same person.
-- Links are written both ways, type seealso; records are never merged.
CREATE OR REPLACE TABLE silver_patient_link AS
WITH latest AS (
    SELECT *
    FROM bronze_resources
    WHERE resource_type = 'Patient'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
)
SELECT
    l.resource_id                                                                 AS patient_id,
    k.index                                                     AS link_index,
    REPLACE(k.value:other.reference::string, 'Patient/', '')         AS other_patient_id,
    k.value:type::string                                             AS link_type
FROM latest l , LATERAL FLATTEN(input => l.raw:link) k;
